DROP TABLE IF EXISTS `candidates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `candidates` (
  `CandidateID` varchar(20) NOT NULL,
  `RequisitionID` varchar(20) DEFAULT NULL,
  `CandidateName` varchar(100) DEFAULT NULL,
  `Gender` varchar(20) DEFAULT NULL,
  `Source` varchar(50) DEFAULT NULL,
  `TotalExperienceYears` decimal(4,2) DEFAULT NULL,
  `CurrentCTC` decimal(12,2) DEFAULT NULL,
  `ExpectedCTC` decimal(12,2) DEFAULT NULL,
  `NoticePeriodDays` int DEFAULT NULL,
  `AppliedDate` date DEFAULT NULL,
  `ScreeningDate` date DEFAULT NULL,
  `Round1Date` date DEFAULT NULL,
  `Round2Date` date DEFAULT NULL,
  `HRRoundDate` date DEFAULT NULL,
  `OfferDate` date DEFAULT NULL,
  `OfferedCTC` decimal(12,2) DEFAULT NULL,
  `OfferResponseDate` date DEFAULT NULL,
  `ExpectedJoiningDate` date DEFAULT NULL,
  `ActualJoiningDate` date DEFAULT NULL,
  `StageReached` varchar(50) DEFAULT NULL,
  `ApplicationStatus` varchar(50) DEFAULT NULL,
  `RejectionOrDeclineReason` varchar(255) DEFAULT NULL,
  `EmployeeID` varchar(20) DEFAULT NULL,
  `SourcingCostINR` decimal(12,2) DEFAULT NULL,
  PRIMARY KEY (`CandidateID`),
