DROP TABLE IF EXISTS `dim_date`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dim_date` (
  `DateKey` int NOT NULL,
  `FullDate` date DEFAULT NULL,
  `DayNo` int DEFAULT NULL,
  `MonthNo` int DEFAULT NULL,
  `MonthName` varchar(20) DEFAULT NULL,
  `MonthShort` varchar(3) DEFAULT NULL,
  `Quarter` varchar(2) DEFAULT NULL,
  `YearNo` int DEFAULT NULL,
  `YearMonth` varchar(10) DEFAULT NULL,
  `FiscalYear` varchar(10) DEFAULT NULL,
  `FiscalQuarter` varchar(3) DEFAULT NULL,
  `FiscalMonthNo` int DEFAULT NULL,
  `WeekOfYear` int DEFAULT NULL,
  `DayName` varchar(10) DEFAULT NULL,
  `IsWeekend` varchar(3) DEFAULT NULL,
  `IsHoliday` varchar(3) DEFAULT NULL,
  `HolidayName` varchar(100) DEFAULT NULL,
  `IsWorkingDay` varchar(3) DEFAULT NULL,
  PRIMARY KEY (`DateKey`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
