--
-- Table structure for table `employees`
--

DROP TABLE IF EXISTS `employees`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `employees` (
  `EmployeeID` varchar(20) NOT NULL,
  `FirstName` varchar(50) DEFAULT NULL,
  `LastName` varchar(50) DEFAULT NULL,
  `FullName` varchar(100) DEFAULT NULL,
  `Gender` varchar(20) DEFAULT NULL,
  `DateOfBirth` date DEFAULT NULL,
  `MaritalStatus` varchar(20) DEFAULT NULL,
  `OfficialEmail` varchar(100) DEFAULT NULL,
  `MobileNumber` varchar(20) DEFAULT NULL,
  `EducationLevel` varchar(50) DEFAULT NULL,
  `Qualification` varchar(50) DEFAULT NULL,
  `Specialization` varchar(50) DEFAULT NULL,
  `HireDate` date DEFAULT NULL,
  `ProbationEndDate` date DEFAULT NULL,
  `EmploymentType` varchar(30) DEFAULT NULL,
  `EmploymentStatus` varchar(30) DEFAULT NULL,
  `ExitDate` date DEFAULT NULL,
  `DepartmentID` varchar(20) DEFAULT NULL,
  `DesignationID` varchar(20) DEFAULT NULL,
  `JobLevel` varchar(10) DEFAULT NULL,
  `LocationID` varchar(20) DEFAULT NULL,
  `ManagerID` varchar(20) DEFAULT NULL,
  `WorkMode` varchar(30) DEFAULT NULL,
  `ShiftType` varchar(30) DEFAULT NULL,
  `BusinessTravel` varchar(30) DEFAULT NULL,
  `DistanceFromHomeKm` int DEFAULT NULL,
  `TotalExperienceAtJoiningYrs` decimal(4,2) DEFAULT NULL,
  `NumCompaniesWorkedBefore` int DEFAULT NULL,
  `StockOptionLevel` int DEFAULT NULL,
  `NoticePeriodDays` int DEFAULT NULL,
  `RecruitmentSource` varchar(50) DEFAULT NULL,
  `SalaryBankName` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`EmployeeID`),
  KEY `fk_employees_department` (`DepartmentID`),
  KEY `fk_employees_designation` (`DesignationID`),
  KEY `fk_employees_location` (`LocationID`),
  KEY `fk_employees_manager` (`ManagerID`),
  CONSTRAINT `fk_employees_department` FOREIGN KEY (`DepartmentID`) REFERENCES `dim_department` (`DepartmentID`),
  CONSTRAINT `fk_employees_designation` FOREIGN KEY (`DesignationID`) REFERENCES `dim_designation` (`DesignationID`),
  CONSTRAINT `fk_employees_location` FOREIGN KEY (`LocationID`) REFERENCES `dim_location` (`LocationID`),
  CONSTRAINT `fk_employees_manager` FOREIGN KEY (`ManagerID`) REFERENCES `employees` (`EmployeeID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `employees`
--

LOCK TABLES `employees` WRITE;
