DROP TABLE IF EXISTS `engagement_survey`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `engagement_survey` (
  `SurveyResponseID` varchar(20) NOT NULL,
  `SurveyYear` int DEFAULT NULL,
  `EmployeeID` varchar(20) DEFAULT NULL,
  `ResponseDate` date DEFAULT NULL,
  `JobSatisfaction` int DEFAULT NULL,
  `EnvironmentSatisfaction` int DEFAULT NULL,
  `WorkLifeBalance` int DEFAULT NULL,
  `RelationshipSatisfaction` int DEFAULT NULL,
  `JobInvolvement` int DEFAULT NULL,
  `ManagerEffectiveness` int DEFAULT NULL,
  `CareerGrowthSatisfaction` int DEFAULT NULL,
  `CompensationSatisfaction` int DEFAULT NULL,
  `eNPS_Score` int DEFAULT NULL,
  `IntentToStay12M` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`SurveyResponseID`),
  KEY `fk_survey_employee` (`EmployeeID`),
  CONSTRAINT `fk_survey_employee` FOREIGN KEY (`EmployeeID`) REFERENCES `employees` (`EmployeeID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
