--
-- Table structure for table `exit_details`
--

DROP TABLE IF EXISTS `exit_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `exit_details` (
  `ExitID` varchar(20) NOT NULL,
  `EmployeeID` varchar(20) DEFAULT NULL,
  `ResignationDate` date DEFAULT NULL,
  `LastWorkingDate` date DEFAULT NULL,
  `NoticePeriodRequiredDays` int DEFAULT NULL,
  `NoticePeriodServedDays` int DEFAULT NULL,
  `ExitType` varchar(50) DEFAULT NULL,
  `ExitReason` varchar(255) DEFAULT NULL,
  `ExitReasonCategory` varchar(100) DEFAULT NULL,
  `RegrettableAttrition` varchar(3) DEFAULT NULL,
  `LastPerformanceRating` varchar(10) DEFAULT NULL,
  `NewEmployerType` varchar(100) DEFAULT NULL,
  `EligibleForRehire` varchar(50) DEFAULT NULL,
  `ExitInterviewCompleted` varchar(3) DEFAULT NULL,
  `FnFSettlementDate` date DEFAULT NULL,
  `DepartmentID` varchar(20) DEFAULT NULL,
  `DesignationID` varchar(20) DEFAULT NULL,
  `LocationID` varchar(20) DEFAULT NULL,
  `ExitStatus` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`ExitID`),
  KEY `fk_exit_employee` (`EmployeeID`),
  KEY `fk_exit_department` (`DepartmentID`),
  KEY `fk_exit_designation` (`DesignationID`),
  KEY `fk_exit_location` (`LocationID`),
  CONSTRAINT `fk_exit_department` FOREIGN KEY (`DepartmentID`) REFERENCES `dim_department` (`DepartmentID`),
  CONSTRAINT `fk_exit_designation` FOREIGN KEY (`DesignationID`) REFERENCES `dim_designation` (`DesignationID`),
  CONSTRAINT `fk_exit_employee` FOREIGN KEY (`EmployeeID`) REFERENCES `employees` (`EmployeeID`),
  CONSTRAINT `fk_exit_location` FOREIGN KEY (`LocationID`) REFERENCES `dim_location` (`LocationID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `exit_details`
--

LOCK TABLES `exit_details` WRITE;
/*!40000 ALTER TABLE `exit_details` DISABLE KEYS */;
