--
-- Table structure for table `job_history`
--

DROP TABLE IF EXISTS `job_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `job_history` (
  `JobHistoryID` varchar(20) NOT NULL,
  `EmployeeID` varchar(20) DEFAULT NULL,
  `EffectiveFrom` date DEFAULT NULL,
  `EffectiveTo` date DEFAULT NULL,
  `EventType` varchar(100) DEFAULT NULL,
  `DepartmentID` varchar(20) DEFAULT NULL,
  `DesignationID` varchar(20) DEFAULT NULL,
  `JobLevel` varchar(10) DEFAULT NULL,
  `LocationID` varchar(20) DEFAULT NULL,
  `IsCurrent` varchar(3) DEFAULT NULL,
  PRIMARY KEY (`JobHistoryID`),
  KEY `fk_history_employee` (`EmployeeID`),
  KEY `fk_history_department` (`DepartmentID`),
  KEY `fk_history_designation` (`DesignationID`),
  KEY `fk_history_location` (`LocationID`),
  CONSTRAINT `fk_history_department` FOREIGN KEY (`DepartmentID`) REFERENCES `dim_department` (`DepartmentID`),
  CONSTRAINT `fk_history_designation` FOREIGN KEY (`DesignationID`) REFERENCES `dim_designation` (`DesignationID`),
  CONSTRAINT `fk_history_employee` FOREIGN KEY (`EmployeeID`) REFERENCES `employees` (`EmployeeID`),
  CONSTRAINT `fk_history_location` FOREIGN KEY (`LocationID`) REFERENCES `dim_location` (`LocationID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `job_history`
--

LOCK TABLES `job_history` WRITE;
