--
-- Table structure for table `job_requisitions`
--

DROP TABLE IF EXISTS `job_requisitions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `job_requisitions` (
  `RequisitionID` varchar(20) NOT NULL,
  `DesignationID` varchar(20) DEFAULT NULL,
  `DepartmentID` varchar(20) DEFAULT NULL,
  `LocationID` varchar(20) DEFAULT NULL,
  `HiringManagerID` varchar(20) DEFAULT NULL,
  `RecruiterID` varchar(20) DEFAULT NULL,
  `RequisitionType` varchar(50) DEFAULT NULL,
  `ReplacementForEmployeeID` varchar(20) DEFAULT NULL,
  `Priority` varchar(20) DEFAULT NULL,
  `NumberOfPositions` int DEFAULT NULL,
  `OpenDate` date DEFAULT NULL,
  `TargetFillDate` date DEFAULT NULL,
  `ClosedDate` date DEFAULT NULL,
  `Status` varchar(30) DEFAULT NULL,
  `BudgetedCTCMin` decimal(12,2) DEFAULT NULL,
  `BudgetedCTCMax` decimal(12,2) DEFAULT NULL,
  PRIMARY KEY (`RequisitionID`),
  KEY `fk_requisition_designation` (`DesignationID`),
  KEY `fk_requisition_department` (`DepartmentID`),
  KEY `fk_requisition_location` (`LocationID`),
  KEY `fk_requisition_manager` (`HiringManagerID`),
  KEY `fk_requisition_recruiter` (`RecruiterID`),
  CONSTRAINT `fk_requisition_department` FOREIGN KEY (`DepartmentID`) REFERENCES `dim_department` (`DepartmentID`),
  CONSTRAINT `fk_requisition_designation` FOREIGN KEY (`DesignationID`) REFERENCES `dim_designation` (`DesignationID`),
  CONSTRAINT `fk_requisition_location` FOREIGN KEY (`LocationID`) REFERENCES `dim_location` (`LocationID`),
  CONSTRAINT `fk_requisition_manager` FOREIGN KEY (`HiringManagerID`) REFERENCES `employees` (`EmployeeID`),
  CONSTRAINT `fk_requisition_recruiter` FOREIGN KEY (`RecruiterID`) REFERENCES `employees` (`EmployeeID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `job_requisitions`
--

LOCK TABLES `job_requisitions` WRITE;
