--
-- Table structure for table `leave_requests`
--

DROP TABLE IF EXISTS `leave_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `leave_requests` (
  `LeaveRequestID` varchar(20) NOT NULL,
  `EmployeeID` varchar(20) DEFAULT NULL,
  `LeaveTypeCode` varchar(10) DEFAULT NULL,
  `AppliedDate` date DEFAULT NULL,
  `StartDate` date DEFAULT NULL,
  `EndDate` date DEFAULT NULL,
  `CalendarDays` int DEFAULT NULL,
  `WorkingDays` int DEFAULT NULL,
  `Status` varchar(30) DEFAULT NULL,
  `ApproverID` varchar(20) DEFAULT NULL,
  `ApprovedOn` date DEFAULT NULL,
  PRIMARY KEY (`LeaveRequestID`),
  KEY `fk_leave_employee` (`EmployeeID`),
  KEY `fk_leave_type` (`LeaveTypeCode`),
  KEY `fk_leave_approver` (`ApproverID`),
  CONSTRAINT `fk_leave_approver` FOREIGN KEY (`ApproverID`) REFERENCES `employees` (`EmployeeID`),
  CONSTRAINT `fk_leave_employee` FOREIGN KEY (`EmployeeID`) REFERENCES `employees` (`EmployeeID`),
  CONSTRAINT `fk_leave_type` FOREIGN KEY (`LeaveTypeCode`) REFERENCES `dim_leavetype` (`LeaveTypeCode`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

