  `TDS` decimal(12,2) DEFAULT NULL,
  `TotalDeductions` decimal(12,2) DEFAULT NULL,
  `NetPay` decimal(12,2) DEFAULT NULL,
  `EPF_Employer` decimal(12,2) DEFAULT NULL,
  `ESI_Employer` decimal(12,2) DEFAULT NULL,
  `GratuityProvision` decimal(12,2) DEFAULT NULL,
  `TotalEmployerCost` decimal(12,2) DEFAULT NULL,
  `PaymentMode` varchar(50) DEFAULT NULL,
  `BankName` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`PayrollID`),
  KEY `fk_payroll_employee` (`EmployeeID`),
  CONSTRAINT `fk_payroll_employee` FOREIGN KEY (`EmployeeID`) REFERENCES `employees` (`EmployeeID`)
