DROP TABLE IF EXISTS `performance_reviews`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `performance_reviews` (
  `PerformanceReviewID` varchar(20) NOT NULL,
  `EmployeeID` varchar(20) DEFAULT NULL,
  `ReviewCycle` varchar(20) DEFAULT NULL,
  `ReviewPeriodStart` date DEFAULT NULL,
  `ReviewPeriodEnd` date DEFAULT NULL,
  `ReviewDate` date DEFAULT NULL,
  `DesignationIDAtReview` varchar(20) DEFAULT NULL,
  `GoalAchievementPct` decimal(5,2) DEFAULT NULL,
  `CompetencyScore` decimal(4,2) DEFAULT NULL,
  `FinalRating` int DEFAULT NULL,
  `RatingLabel` varchar(50) DEFAULT NULL,
  `PotentialRating` varchar(20) DEFAULT NULL,
  `NineBoxCategory` varchar(50) DEFAULT NULL,
  `PromotionRecommended` varchar(3) DEFAULT NULL,
  `PIPInitiated` varchar(3) DEFAULT NULL,
  `ReviewerID` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`PerformanceReviewID`),
  KEY `fk_review_employee` (`EmployeeID`),
  KEY `fk_review_designation` (`DesignationIDAtReview`),
  KEY `fk_review_reviewer` (`ReviewerID`),
  CONSTRAINT `fk_review_designation` FOREIGN KEY (`DesignationIDAtReview`) REFERENCES `dim_designation` (`DesignationID`),
  CONSTRAINT `fk_review_employee` FOREIGN KEY (`EmployeeID`) REFERENCES `employees` (`EmployeeID`),
  CONSTRAINT `fk_review_reviewer` FOREIGN KEY (`ReviewerID`) REFERENCES `employees` (`EmployeeID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

