  `AnnualHRA` decimal(12,2) DEFAULT NULL,
  `AnnualSpecialAllowance` decimal(12,2) DEFAULT NULL,
  `EmployerPF_Annual` decimal(12,2) DEFAULT NULL,
  `Gratuity_Annual` decimal(12,2) DEFAULT NULL,
  `HikePct` decimal(5,2) DEFAULT NULL,
  `LinkedRatingFY` varchar(20) DEFAULT NULL,
  `IsCurrent` varchar(3) DEFAULT NULL,
  PRIMARY KEY (`SalaryRecordID`),
  KEY `fk_salary_employee` (`EmployeeID`),
  KEY `fk_salary_designation` (`DesignationID`),
  CONSTRAINT `fk_salary_designation` FOREIGN KEY (`DesignationID`) REFERENCES `dim_designation` (`DesignationID`),
  CONSTRAINT `fk_salary_employee` FOREIGN KEY (`EmployeeID`) REFERENCES `employees` (`EmployeeID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
